begin;
create or replace function public.receive_measurement(p_measurement_id uuid,p_account_id uuid,p_received_on date,p_amount numeric default null) returns uuid language plpgsql security invoker set search_path='' as $$declare v_m public.measurements%rowtype;v_link public.measurement_finance_links%rowtype;v_installment public.financial_installments%rowtype;v_account public.financial_accounts%rowtype;v_paid numeric(18,2);v_remaining numeric(18,2);v_receive numeric(18,2);v_settlement uuid;v_key text;begin if p_received_on is null then raise exception 'received date is required';end if;select * into v_m from public.measurements where id=p_measurement_id for update;if not found or not app_private.can_access_company(v_m.tenant_id,v_m.company_id) then raise exception 'measurement not found or inaccessible';end if;select * into v_link from public.measurement_finance_links where tenant_id=v_m.tenant_id and company_id=v_m.company_id and measurement_id=v_m.id;if not found then raise exception 'measurement has no generated receivable';end if;select * into v_installment from public.financial_installments where tenant_id=v_m.tenant_id and company_id=v_m.company_id and id=v_link.financial_installment_id for update;select * into v_account from public.financial_accounts where tenant_id=v_m.tenant_id and company_id=v_m.company_id and id=p_account_id and status='active';if not found then raise exception 'active financial account not found in measurement company';end if;select coalesce(sum(amount),0) into v_paid from public.financial_settlements where tenant_id=v_m.tenant_id and company_id=v_m.company_id and installment_id=v_installment.id;v_remaining:=round(v_installment.amount-v_paid,2);if v_remaining<=0 then raise exception 'measurement receivable is already fully settled';end if;v_receive:=coalesce(p_amount,v_remaining);if v_receive<=0 or v_receive>v_remaining then raise exception 'received amount must be positive and cannot exceed remaining receivable';end if;v_key:='measurement-receipt:'||v_m.id::text||':'||(select count(*)+1 from public.financial_settlements where tenant_id=v_m.tenant_id and company_id=v_m.company_id and installment_id=v_installment.id)::text;insert into public.financial_settlements(tenant_id,company_id,installment_id,account_id,settled_on,amount,idempotency_key,notes,created_by) values(v_m.tenant_id,v_m.company_id,v_installment.id,p_account_id,p_received_on,v_receive,v_key,'Recebimento de medição da Engenharia: '||v_m.id::text,(select auth.uid())) returning id into v_settlement;return v_settlement;end$$;
revoke all on function public.receive_measurement(uuid,uuid,date,numeric) from public,anon;grant execute on function public.receive_measurement(uuid,uuid,date,numeric) to authenticated;
create view public.measurement_receipt_status with(security_invoker=true) as select l.tenant_id,l.company_id,l.measurement_id,l.financial_entry_id,l.financial_installment_id,i.amount receivable_amount,coalesce(sum(s.amount),0)::numeric(18,2) received_amount,(i.amount-coalesce(sum(s.amount),0))::numeric(18,2) remaining_amount,case when coalesce(sum(s.amount),0)=0 then 'pending' when coalesce(sum(s.amount),0)<i.amount then 'partial' else 'paid' end receipt_status,max(s.settled_on) last_received_on from public.measurement_finance_links l join public.financial_installments i on i.tenant_id=l.tenant_id and i.company_id=l.company_id and i.id=l.financial_installment_id left join public.financial_settlements s on s.tenant_id=i.tenant_id and s.company_id=i.company_id and s.installment_id=i.id group by l.tenant_id,l.company_id,l.measurement_id,l.financial_entry_id,l.financial_installment_id,i.amount;
commit;